						if(++c[axis]<bs)b=system.dof(level,brick,c[0],c[1],c[2]);
						else{other_brick=meta.same_level_neighbor[2*axis+1];if(other_brick>=0&&source.bricks[other_brick].active()){c[axis]=0;b=system.dof(level,other_brick,c[0],c[1],c[2]);}}
						if(b<0||!system.active[b])continue;const BrickMetadata& other_meta=source.bricks[other_brick];
						const Vec3d nominal_b=other_meta.origin+Vec3d{(c[0]+.5)*h,(c[1]+.5)*h,(c[2]+.5)*h};
						const double shift_a=std::sqrt(length2(system.centroid[a]-nominal_a)),shift_b=std::sqrt(length2(system.centroid[b]-nominal_b));
						const bool merged=std::abs(system.volume[a]-nominal_volume)>1e-10*nominal_volume||std::abs(system.volume[b]-nominal_volume)>1e-10*nominal_volume||shift_a>1e-10*h||shift_b>1e-10*h;
						if(!merged)continue;Vec3d ideal{};ideal[axis]=h;const Vec3d displacement=system.centroid[b]-system.centroid[a];const double score=std::sqrt(length2(displacement-ideal))/h;
